import React, { useState } from 'react';
import ResumeUploader from '../../components/ResumeUploader/ResumeUploader';
import ResumePreview from '../../components/ResumePreview/ResumePreview';
import ExtractedDetails from '../../components/ExtractedDetails/ExtractedDetails';
import './ResumeAnalysis.css';

/**
 * Page-level container for the Resume Analysis feature.
 */
const ResumeAnalysis = () => {
  const [analysisData, setAnalysisData] = useState(null);

  return (
    <section className="resume-analysis-page">
      <header className="resume-analysis-page__header">
        <h1>Resume Analysis</h1>
        <p>Upload a resume and extract structured profile details for interview preparation.</p>
      </header>

      <div className="resume-analysis-page__content">
        <ResumeUploader onAnalysisComplete={setAnalysisData} />
        <ResumePreview analysisData={analysisData} />
        <ExtractedDetails analysisData={analysisData} />
      </div>
    </section>
  );
};

export default ResumeAnalysis;
